<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'; import * as accountsAPI from '@shared-api/admin/accounts'; import * as antigravityAPI from '@shared-api/admin/antigravity'; import * as geminiAPI from '@shared-api/admin/gemini'; import * as grokAPI from '@shared-api/admin/grok'; import type { Account } from '@/types'; import SurfaceDialog from '@/components/base/SurfaceDialog.vue'; import { DialogWidth } from '@/components/base/dialog'; import { AccountOAuthMethod, buildOAuthCredentialPayload } from '@/features/admin/resources/account'; import { useAppStore } from '@/stores/app'
const props = defineProps<{ show: boolean; account: Account | null }>(); const emit = defineEmits<{ close: []; updated: [] }>(); const app = useAppStore(); const method = ref(AccountOAuthMethod.CODE); const loading = ref(false); const authUrl = ref(''); const sessionId = ref(''); const state = ref(''); const form = reactive({ code: '', refreshToken: '', sso: '', password: '', oauthType: 'code_assist', projectId: '' })
const methodLabels: Record<AccountOAuthMethod, string> = { [AccountOAuthMethod.CODE]: '浏览器授权', [AccountOAuthMethod.REFRESH_TOKEN]: 'Refresh Token', [AccountOAuthMethod.SSO_COOKIE]: 'SSO / Session Cookie', [AccountOAuthMethod.PASSWORD]: '邮箱密码' }
const methods = computed<AccountOAuthMethod[]>(() => { if (props.account?.platform === 'openai' || props.account?.platform === 'antigravity') return [AccountOAuthMethod.CODE, AccountOAuthMethod.REFRESH_TOKEN]; if (props.account?.platform === 'grok') return Object.values(AccountOAuthMethod); if (props.account?.platform === 'anthropic') return [AccountOAuthMethod.CODE, AccountOAuthMethod.SSO_COOKIE]; return [AccountOAuthMethod.CODE] })
const canGenerate = computed(() => Boolean(props.account) && method.value === AccountOAuthMethod.CODE)
async function generate(): Promise<void> { if (!props.account || loading.value) return; loading.value = true; try { let result: { auth_url: string; session_id: string; state?: string }; const proxy = props.account.proxy_id || undefined; if (props.account.platform === 'openai') result = await accountsAPI.generateAuthUrl('/admin/openai/generate-auth-url', { proxy_id: proxy }); else if (props.account.platform === 'gemini') result = await geminiAPI.generateAuthUrl({ proxy_id: proxy, project_id: form.projectId || undefined, oauth_type: form.oauthType as 'code_assist' | 'google_one' | 'ai_studio' }); else if (props.account.platform === 'antigravity') result = await antigravityAPI.generateAuthUrl({ proxy_id: proxy }); else if (props.account.platform === 'grok') result = await grokAPI.generateAuthUrl({ proxy_id: proxy }); else result = await accountsAPI.generateAuthUrl(props.account.type === 'setup-token' ? '/admin/accounts/generate-setup-token-url' : '/admin/accounts/generate-auth-url', { proxy_id: proxy }); authUrl.value = result.auth_url; sessionId.value = result.session_id; state.value = result.state || (() => { try { return new URL(result.auth_url).searchParams.get('state') || '' } catch { return '' } })(); app.showSuccess('授权链接已生成') } catch (caught) { app.showError((caught as { message?: string }).message || '生成授权链接失败') } finally { loading.value = false } }
async function applyCredentials(token: Record<string, unknown>): Promise<void> { if (!props.account) return; const built = buildOAuthCredentialPayload(props.account.platform, token, { refreshTokenFallback: form.refreshToken.trim() || undefined, geminiOAuthType: form.oauthType, geminiTierId: typeof props.account.credentials?.tier_id === 'string' ? props.account.credentials.tier_id : undefined }); await accountsAPI.applyOAuthCredentials(props.account.id, { type: props.account.type === 'setup-token' ? 'setup-token' : 'oauth', credentials: { ...(props.account.credentials || {}), ...built.credentials }, extra: built.extra }); app.showSuccess('账号已重新授权'); emit('updated'); emit('close') }
async function complete(): Promise<void> { if (!props.account || loading.value) return; loading.value = true; try { const proxy = props.account.proxy_id || undefined; let token: Record<string, unknown>; if (method.value === AccountOAuthMethod.REFRESH_TOKEN) { if (props.account.platform === 'openai') token = await accountsAPI.refreshOpenAIToken(form.refreshToken, proxy); else if (props.account.platform === 'antigravity') token = await antigravityAPI.refreshAntigravityToken(form.refreshToken, proxy); else if (props.account.platform === 'grok') token = await grokAPI.refreshGrokToken(form.refreshToken, proxy); else throw new Error('该平台不支持在此直接验证 Refresh Token') } else if (method.value === AccountOAuthMethod.SSO_COOKIE) { if (props.account.platform === 'grok') token = await grokAPI.validateSSOToken(form.sso, proxy); else token = await accountsAPI.exchangeCode(props.account.type === 'setup-token' ? '/admin/accounts/setup-token-cookie-auth' : '/admin/accounts/cookie-auth', { session_id: '', code: form.sso, proxy_id: proxy }) } else if (method.value === AccountOAuthMethod.PASSWORD) { if (props.account.platform !== 'grok') throw new Error('密码授权仅适用于 Grok'); token = await grokAPI.authorizePassword(form.password, proxy) } else { if (!sessionId.value || !form.code.trim()) throw new Error('请先生成授权链接并填写回调 code'); if (props.account.platform === 'openai') token = await accountsAPI.exchangeCode('/admin/openai/exchange-code', { session_id: sessionId.value, code: form.code.trim(), state: state.value, proxy_id: proxy }); else if (props.account.platform === 'gemini') token = await geminiAPI.exchangeCode({ session_id: sessionId.value, state: state.value, code: form.code.trim(), proxy_id: proxy, oauth_type: form.oauthType as 'code_assist' | 'google_one' | 'ai_studio' }); else if (props.account.platform === 'antigravity') token = await antigravityAPI.exchangeCode({ session_id: sessionId.value, state: state.value, code: form.code.trim(), proxy_id: proxy }); else if (props.account.platform === 'grok') token = await grokAPI.exchangeCode({ session_id: sessionId.value, state: state.value, code: form.code.trim(), proxy_id: proxy }); else token = await accountsAPI.exchangeCode(props.account.type === 'setup-token' ? '/admin/accounts/exchange-setup-token-code' : '/admin/accounts/exchange-code', { session_id: sessionId.value, code: form.code.trim(), proxy_id: proxy }) } await applyCredentials(token) } catch (caught) { app.showError((caught as { message?: string }).message || '授权失败') } finally { loading.value = false } }
watch(() => props.show, (show) => { if (show) { method.value = methods.value[0]; authUrl.value = ''; sessionId.value = ''; state.value = ''; Object.assign(form, { code: '', refreshToken: '', sso: '', password: '', oauthType: typeof props.account?.credentials?.oauth_type === 'string' ? props.account.credentials.oauth_type : 'code_assist', projectId: typeof props.account?.credentials?.project_id === 'string' ? props.account.credentials.project_id : '' }); if (props.account?.platform === 'gemini') void geminiAPI.getCapabilities().catch(() => undefined); if (props.account?.platform === 'grok') void grokAPI.getCapabilities().catch(() => undefined) } })
</script>
<template><SurfaceDialog :show="show" :title="`重新授权 · ${account?.name || ''}`" description="令牌只提交给现有共享 API；密码与 SSO Cookie 不写入账号凭据，模型映射等非敏感配置会继续保留。" :width="DialogWidth.WIDE" @close="emit('close')"><div class="resource-form-stack"><div class="resource-tabs"><button v-for="item in methods" :key="item" :aria-selected="method === item" @click="method = item">{{ methodLabels[item] }}</button></div><template v-if="method === AccountOAuthMethod.CODE"><div v-if="account?.platform === 'gemini'" class="resource-form-grid"><label>OAuth 类型<select v-model="form.oauthType"><option value="code_assist">Code Assist</option><option value="google_one">Google One</option><option value="ai_studio">AI Studio</option></select></label><label>Project ID<input v-model="form.projectId" /></label></div><button class="resource-button" :disabled="!canGenerate || loading" @click="generate">{{ loading ? '生成中…' : '生成授权链接' }}</button><div v-if="authUrl" class="auth-link"><a :href="authUrl" target="_blank" rel="noopener noreferrer">在新窗口打开授权页 ↗</a><code>{{ authUrl }}</code></div><div class="resource-form-grid"><label>回调 code<input v-model="form.code" /></label><label v-if="state || account?.platform !== 'anthropic'">state<input v-model="state" /></label></div></template><label v-else-if="method === AccountOAuthMethod.REFRESH_TOKEN">Refresh Token<textarea v-model="form.refreshToken" rows="5" /></label><label v-else-if="method === AccountOAuthMethod.SSO_COOKIE">SSO / Session Cookie<textarea v-model="form.sso" rows="5" /></label><label v-else>Grok 邮箱与密码<input v-model="form.password" type="password" placeholder="email@example.com----password" /></label></div><template #footer><button class="button button--secondary" @click="emit('close')">取消</button><button class="button button--primary" :disabled="loading" @click="complete">{{ loading ? '验证中…' : '完成授权' }}</button></template></SurfaceDialog></template>
<style scoped>.auth-link { padding: 12px; display: grid; gap: 8px; background: var(--accent-soft); border-radius: 10px; }.auth-link a { color: var(--accent); font-weight: 700; }.auth-link code { overflow-wrap: anywhere; color: var(--text-secondary); font-size: var(--font-meta); }</style>
